// First query: SELECT * FROM Posts WHERE Published = 1
var posts = await dbContext.Posts
    .Where(p => p.IsPublished)
    .ToListAsync();

// N additional queries — one per post
foreach (var post in posts)
{
    // SELECT * FROM Authors WHERE Id = @p0
    Console.WriteLine(post.Author.FullName);
}

var posts = await dbContext.Posts
    .Include(p => p.Author)
    .Where(p => p.IsPublished)
    .ToListAsync();

// No additional queries — Author is already loaded
foreach (var post in posts)
{
    Console.WriteLine(post.Author.FullName);
}

var postSummaries = await dbContext.Posts
    .Where(p => p.IsPublished)
    .Select(p => new PostSummaryDto
    {
        Title = p.Title,
        AuthorName = p.Author.FullName,
        PublishedAt = p.PublishedAt
    })
    .ToListAsync();

foreach (var summary in postSummaries)
{
    Console.WriteLine($"{summary.Title} by {summary.AuthorName}");
}
